/**
 * ══════════════════════════════════════════════════════════════════
 *  platform-news.js  v2.0
 *  محرك الأخبار الذكي — Realtime + Vibration + Acknowledgment
 *  © 2026 NAFAS FOR ARTIFICIAL INTELLIGENCE · CN-6573712
 *
 *  الاستخدام: أضف <div id="eduos-news-panel"></div> ثم EduOSNews.init()
 *
 *  الجديد في v2:
 *   ✅ Supabase Realtime — ظهور فوري بلا تحديث الصفحة
 *   ✅ بنر طوارئ عاجل يعلو الشاشة كاملة
 *   ✅ اهتزاز: single / triple / continuous
 *   ✅ زر استلمت — يوقف الاهتزاز ويُسجَّل في DB
 *   ✅ SMS fallback للطوارئ الحرجة
 *   ✅ إعلانات الصف من المعلم/ة
 *   ✅ A-D Framework integration
 * ══════════════════════════════════════════════════════════════════
 */

window.EduOSNews = (() => {
  'use strict';

  const SB_URL  = 'https://zuyizaiugpmhmeycqton.supabase.co';
  const SB_ANON = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Inp1eWl6YWl1Z3BtaG1leWNxdG9uIiwicm9sZSI6ImFub24iLCJpYXQiOjE3MTU1MjI4MDAsImV4cCI6MjAzMTA5ODgwMH0.Vf4uGJDwvAg1V3n0h1OAtW35A1FMKbEXRaGzFxXfx48';
  const FN_URL  = `${SB_URL}/functions/v1/smart-news-engine`;

  // ── Vibration controller ────────────────────────────────────
  let _vibInterval = null;

  function vibrate(level) {
    if (!navigator.vibrate) return;
    stopVibration();
    if (level === 'single')     navigator.vibrate([300]);
    if (level === 'triple')     navigator.vibrate([300, 100, 300, 100, 300]);
    if (level === 'continuous') {
      navigator.vibrate([500, 300]);
      _vibInterval = setInterval(() => navigator.vibrate([500, 300]), 2000);
    }
  }

  function stopVibration() {
    if (_vibInterval) { clearInterval(_vibInterval); _vibInterval = null; }
    if (navigator.vibrate) navigator.vibrate(0);
  }

  // ── Sound alert ────────────────────────────────────────────
  function playAlert(level) {
    try {
      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      const oscillator = ctx.createOscillator();
      const gain = ctx.createGain();
      oscillator.connect(gain);
      gain.connect(ctx.destination);
      oscillator.frequency.value = level === 'continuous' ? 880 : 660;
      oscillator.type = 'sine';
      gain.gain.setValueAtTime(0.3, ctx.currentTime);
      oscillator.start();
      if (level === 'continuous') {
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 2);
        oscillator.stop(ctx.currentTime + 2);
      } else {
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.8);
        oscillator.stop(ctx.currentTime + 0.8);
      }
    } catch (e) { /* audio blocked */ }
  }

  // ── Get current user ────────────────────────────────────────
  function getUser() {
    try { return JSON.parse(sessionStorage.getItem('edoos_user') || '{}'); }
    catch { return {}; }
  }

  // ── EMERGENCY BANNER ────────────────────────────────────────
  const _activeEmergencies = new Set();

  function showEmergencyBanner(item) {
    if (_activeEmergencies.has(item.id)) return;
    _activeEmergencies.add(item.id);

    // Vibrate + sound
    vibrate(item.vibration_level || 'triple');
    playAlert(item.vibration_level || 'triple');

    // Inject keyframe animation
    if (!document.getElementById('eduos-emergency-css')) {
      const style = document.createElement('style');
      style.id = 'eduos-emergency-css';
      style.textContent = `
        @keyframes eduos-flash { 0%,100%{opacity:1} 50%{opacity:.7} }
        @keyframes eduos-slidein { from{transform:translateY(-100%)} to{transform:translateY(0)} }
        @keyframes eduos-pulse-border { 0%,100%{box-shadow:0 0 0 0 rgba(220,38,38,.6)} 50%{box-shadow:0 0 0 12px rgba(220,38,38,0)} }
      `;
      document.head.appendChild(style);
    }

    const banner = document.createElement('div');
    banner.id = `eduos-emergency-${item.id}`;
    banner.dir = 'rtl';
    banner.style.cssText = `
      position:fixed;top:0;left:0;right:0;z-index:999999;
      background:linear-gradient(135deg,#991B1B,#DC2626);
      color:white;padding:0;
      animation:eduos-slidein .4s ease,eduos-flash 1.5s infinite;
      font-family:'Tajawal',Arial,sans-serif;
      box-shadow:0 4px 20px rgba(0,0,0,.5);
    `;
    banner.innerHTML = `
      <div style="display:flex;align-items:center;gap:16px;padding:14px 20px;flex-wrap:wrap;">
        <div style="
          background:rgba(255,255,255,.2);border-radius:50%;
          width:44px;height:44px;display:flex;align-items:center;justify-content:center;
          font-size:22px;flex-shrink:0;animation:eduos-pulse-border 1s infinite;
        ">🚨</div>
        <div style="flex:1;min-width:200px;">
          <div style="font-size:13px;opacity:.85;margin-bottom:2px;">
            🔴 تنبيه طارئ عاجل
            ${item.source_name ? `· ${item.source_name}` : ''}
          </div>
          <div style="font-size:16px;font-weight:700;line-height:1.4;">${item.title}</div>
          ${item.content ? `<div style="font-size:13px;opacity:.9;margin-top:4px;">${item.content}</div>` : ''}
        </div>
        <div style="display:flex;gap:10px;flex-shrink:0;align-items:center;">
          ${item.requires_ack ? `
          <button onclick="EduOSNews.acknowledge('${item.id}','${item.type || 'news'}')"
            style="
              background:white;color:#DC2626;border:none;border-radius:8px;
              padding:10px 20px;font-size:14px;font-weight:700;cursor:pointer;
              font-family:'Tajawal',Arial,sans-serif;
            ">✅ استلمت</button>` : ''}
          <button onclick="EduOSNews.dismissBanner('${item.id}')"
            style="
              background:rgba(255,255,255,.15);color:white;border:1px solid rgba(255,255,255,.3);
              border-radius:8px;padding:10px 16px;font-size:13px;cursor:pointer;
              font-family:'Tajawal',Arial,sans-serif;
            ">✕</button>
        </div>
      </div>
    `;

    document.body.insertBefore(banner, document.body.firstChild);

    // Push page content down
    document.body.style.marginTop = (banner.offsetHeight + 4) + 'px';
  }

  // ── SUPABASE REALTIME ────────────────────────────────────────
  let _realtimeConn = null;

  function initRealtime(user) {
    if (typeof window.supabase !== 'undefined') {
      _startRealtime(window.supabase, user);
      return;
    }

    // Load Supabase JS if not present
    const script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/dist/umd/supabase.min.js';
    script.onload = () => {
      const sbClient = window.supabase.createClient(SB_URL, SB_ANON);
      _startRealtime(sbClient, user);
    };
    document.head.appendChild(script);
  }

  function _startRealtime(sbClient, user) {
    if (_realtimeConn) { sbClient.removeChannel(_realtimeConn); }

    _realtimeConn = sbClient.channel('eduos-news-live')
      // Watch education_news inserts
      .on('postgres_changes', {
        event: 'INSERT',
        schema: 'public',
        table: 'education_news',
      }, payload => {
        const item = payload.new;
        if (!item.is_active) return;

        // Check if this role should see it
        const allowed = ROLE_AUDIENCE[user.role] || ['all'];
        const itemAud = item.audience || ['all'];
        const shouldSee = itemAud.some(a => allowed.includes(a));
        if (!shouldSee) return;

        // Emergency → banner immediately
        if (item.category === 'emergency' || item.severity === 'high') {
          showEmergencyBanner({
            id: item.id, type: 'news',
            title: item.title_ar,
            content: item['content_' + user.role] || item.body_ar,
            source_name: item.source_name,
            vibration_level: item.vibration_level || 'triple',
            requires_ack: item.requires_ack,
          });
        }

        // Add to news panel without reload
        _prependNewsItem(item, user.role);
        _showLiveToast(`📰 خبر جديد: ${item.title_ar?.substring(0, 60)}...`);
      })
      // Watch class_announcements inserts
      .on('postgres_changes', {
        event: 'INSERT',
        schema: 'public',
        table: 'class_announcements',
      }, payload => {
        const item = payload.new;
        if (!item.is_active) return;

        // Check if user's class is in item.class_ids
        if (user.class_id && !item.class_ids?.includes(user.class_id)) return;

        if (item.severity === 'high') {
          showEmergencyBanner({
            id: item.id, type: 'class_ann',
            title: item.title_ar,
            content: item.body_ar,
            source_name: item.teacher_name,
            vibration_level: item.vibration_level || 'single',
            requires_ack: item.requires_ack,
          });
        } else {
          _showLiveToast(`📢 ${item.teacher_name || 'معلم/ة'}: ${item.title_ar?.substring(0, 50)}`);
        }

        _prependNewsItem({ ...item, category: item.ann_type, source_name: item.teacher_name }, user.role);
      })
      .subscribe();
  }

  const ROLE_AUDIENCE = {
    principal: ['all','staff','principal','teacher','secretary','security','nurse','technician'],
    admin: ['all','staff','principal'], teacher: ['all','staff','teacher'],
    security: ['all','staff','security'], nurse: ['all','staff','nurse'],
    technician: ['all','staff','technician'], secretary: ['all','staff','secretary'],
    observer: ['all','staff','principal'], parent: ['all','parent'], student: ['all','student'],
    specialist: ['all','staff','teacher'], social_worker: ['all','staff'],
  };

  // ── Live toast notification ────────────────────────────────
  function _showLiveToast(msg) {
    const t = document.createElement('div');
    t.dir = 'rtl';
    t.style.cssText = `
      position:fixed;bottom:24px;right:24px;z-index:99998;
      background:#1F2937;color:white;padding:12px 20px;border-radius:12px;
      font-family:'Tajawal',Arial,sans-serif;font-size:14px;
      box-shadow:0 4px 16px rgba(0,0,0,.3);
      animation:eduos-slidein .3s ease;max-width:340px;
    `;
    t.textContent = msg;
    document.body.appendChild(t);
    setTimeout(() => t.remove(), 4500);
  }

  // ── Prepend new item to panel ──────────────────────────────
  function _prependNewsItem(item, role) {
    const container = document.getElementById('eduos-news-items');
    if (!container) return;

    const mapped = {
      id: item.id, type: item.source_type === 'internal' || item.ann_type ? 'class' : 'official',
      category: item.category || item.ann_type || 'academic',
      severity: item.severity || 'normal',
      source_name: item.source_name, title: item.title_ar, body: item.body_ar,
      content: item['content_' + role] || item.body_ar,
      published_at: item.created_at || new Date().toISOString(),
      vibration_level: item.vibration_level, requires_ack: item.requires_ack,
    };

    const div = document.createElement('div');
    div.innerHTML = renderItem(mapped);
    div.firstElementChild.style.animation = 'eduos-slidein .4s ease';
    div.firstElementChild.style.borderColor = '#22D3EE';
    container.insertBefore(div.firstElementChild, container.firstChild);

    // Remove "no news" placeholder if exists
    const placeholder = container.querySelector('.no-news-placeholder');
    if (placeholder) placeholder.remove();
  }

  // ── Category metadata ────────────────────────────────────
  const CATEGORY_META = {
    emergency:   { icon: '🚨', label: 'طوارئ',             color: '#DC2626', bg: '#FEF2F2' },
    decision:    { icon: '📋', label: 'قرارات رسمية',      color: '#7C3AED', bg: '#F5F3FF' },
    curriculum:  { icon: '📚', label: 'مناهج وكتب',        color: '#0369A1', bg: '#EFF6FF' },
    calendar:    { icon: '🗓️', label: 'تقويم وإجازات',   color: '#065F46', bg: '#ECFDF5' },
    exam:        { icon: '📝', label: 'اختبارات',           color: '#B45309', bg: '#FFFBEB' },
    quiz:        { icon: '❓', label: 'اختبار قصير',        color: '#EA580C', bg: '#FFF7ED' },
    homework:    { icon: '📓', label: 'واجب منزلي',         color: '#1D4ED8', bg: '#EFF6FF' },
    activity:    { icon: '🎨', label: 'نشاط',               color: '#7C3AED', bg: '#F5F3FF' },
    absence:     { icon: '⚠️', label: 'غياب المعلم/ة',    color: '#D97706', bg: '#FFFBEB' },
    survey:      { icon: '📊', label: 'استبيان',            color: '#0891B2', bg: '#ECFEFF' },
    teacher_dev: { icon: '👩‍🏫', label: 'تطوير معلمين',   color: '#6D28D9', bg: '#EDE9FE' },
    academic:    { icon: '🎓', label: 'مستجدات أكاديمية',  color: '#1D4ED8', bg: '#EFF6FF' },
    competition: { icon: '🏆', label: 'مسابقات',            color: '#047857', bg: '#ECFDF5' },
    general:     { icon: '📌', label: 'إعلان',              color: '#374151', bg: '#F9FAFB' },
  };

  function formatDate(iso) {
    if (!iso) return '';
    return new Date(iso).toLocaleDateString('ar-AE', {
      weekday: 'short', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit',
    });
  }

  function renderItem(item) {
    const meta = CATEGORY_META[item.category] || CATEGORY_META.academic;
    const isEmergency = item.category === 'emergency' || item.severity === 'high';

    return `
      <div style="
        background:white;
        border:1px solid ${isEmergency ? '#FCA5A5' : '#E5E7EB'};
        border-right:4px solid ${meta.color};
        border-radius:10px;padding:14px 16px;
        margin-bottom:8px;
        ${isEmergency ? 'box-shadow:0 2px 12px rgba(220,38,38,.15);' : ''}
        transition:box-shadow .15s;
      "
      onmouseover="this.style.boxShadow='0 2px 10px rgba(0,0,0,.08)'"
      onmouseout="this.style.boxShadow='${isEmergency ? '0 2px 12px rgba(220,38,38,.15)' : 'none'}'">

        <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;flex-wrap:wrap;">
          <div style="flex:1;">
            <div style="display:flex;align-items:center;gap:6px;margin-bottom:6px;flex-wrap:wrap;">
              <span style="
                background:${meta.bg};color:${meta.color};
                font-size:11px;font-weight:700;padding:2px 10px;border-radius:20px;
                font-family:'Tajawal',Arial,sans-serif;
              ">${meta.icon} ${meta.label}</span>
              ${item.severity === 'high' ? `<span style="background:#FEE2E2;color:#DC2626;font-size:11px;font-weight:700;padding:2px 10px;border-radius:20px;font-family:'Tajawal',Arial,sans-serif;">🔴 عاجل</span>` : ''}
              ${item.severity === 'medium' ? `<span style="background:#FEF3C7;color:#D97706;font-size:11px;padding:2px 8px;border-radius:20px;font-family:'Tajawal',Arial,sans-serif;">⚠️ مهم</span>` : ''}
            </div>
            <div style="font-size:15px;font-weight:700;color:#111827;font-family:'Tajawal',Arial,sans-serif;line-height:1.5;margin-bottom:6px;">
              ${item.title || ''}
            </div>
            ${item.content ? `<div style="font-size:13px;color:#374151;font-family:'Tajawal',Arial,sans-serif;line-height:1.7;">${item.content}</div>` : ''}
          </div>
        </div>

        <div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px;padding-top:8px;border-top:1px solid #F3F4F6;flex-wrap:wrap;gap:6px;">
          <span style="font-size:11px;color:#9CA3AF;font-family:'Tajawal',Arial,sans-serif;">
            📌 ${item.source_name || 'مصدر رسمي'}
          </span>
          <div style="display:flex;gap:8px;align-items:center;">
            ${item.requires_ack ? `
            <button onclick="EduOSNews.acknowledge('${item.id}','${item.type || 'news'}')"
              style="background:#D1FAE5;color:#065F46;border:none;border-radius:6px;
                padding:4px 12px;font-size:12px;cursor:pointer;font-family:'Tajawal',Arial,sans-serif;">
              ✅ استلمت
            </button>` : ''}
            <span style="font-size:11px;color:#9CA3AF;font-family:'Tajawal',Arial,sans-serif;">
              ${formatDate(item.published_at)}
            </span>
          </div>
        </div>
      </div>
    `;
  }

  function renderSkeleton() {
    return `<style>@keyframes pulse{0%,100%{opacity:1}50%{opacity:.5}}</style>` +
      Array(3).fill(0).map(() => `
        <div style="background:#F9FAFB;border-radius:10px;padding:16px;margin-bottom:10px;animation:pulse 1.5s infinite;">
          <div style="height:14px;background:#E5E7EB;border-radius:4px;margin-bottom:8px;width:30%;"></div>
          <div style="height:16px;background:#E5E7EB;border-radius:4px;margin-bottom:8px;width:70%;"></div>
          <div style="height:12px;background:#E5E7EB;border-radius:4px;width:90%;"></div>
        </div>
      `).join('');
  }

  function buildPanel() {
    return `
      <div dir="rtl" style="
        background:white;border-radius:14px;
        border:1px solid #E5E7EB;
        box-shadow:0 1px 4px rgba(0,0,0,.06);
        padding:20px;font-family:'Tajawal',Arial,sans-serif;
      ">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;">
          <div style="display:flex;align-items:center;gap:10px;">
            <div style="
              width:38px;height:38px;border-radius:10px;
              background:linear-gradient(135deg,#6C3DD6,#22D3EE);
              display:flex;align-items:center;justify-content:center;font-size:18px;
            ">📰</div>
            <div>
              <div style="font-size:16px;font-weight:700;color:#111827;">أخبار التعليم</div>
              <div style="font-size:11px;color:#9CA3AF;">مباشر من المصادر الرسمية</div>
            </div>
          </div>
          <div style="display:flex;gap:8px;align-items:center;">
            <div id="eduos-news-live-indicator" style="
              width:8px;height:8px;border-radius:50%;background:#10B981;
              box-shadow:0 0 0 2px rgba(16,185,129,.3);display:none;
            " title="متصل بالوقت الفعلي"></div>
            <button onclick="EduOSNews.refresh()" style="
              background:#F3F4F6;border:none;border-radius:8px;
              padding:6px 14px;font-size:12px;color:#374151;cursor:pointer;
              font-family:'Tajawal',Arial,sans-serif;
            ">🔄 تحديث</button>
          </div>
        </div>
        <div id="eduos-news-items" style="max-height:70vh;overflow-y:auto;padding-left:2px;">
          ${renderSkeleton()}
        </div>
      </div>
    `;
  }

  async function loadNews() {
    const user = getUser();
    if (!user.role) return;
    const container = document.getElementById('eduos-news-items');
    if (!container) return;

    try {
      const resp = await fetch(FN_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${SB_ANON}` },
        body: JSON.stringify({
          action: 'fetch', role: user.role,
          school_id: user.school_id || null,
          class_id: user.class_id || null,
          limit: 20,
        }),
      });
      const data = await resp.json();
      if (!data.ok || !data.news?.length) {
        container.innerHTML = `<div class="no-news-placeholder" dir="rtl" style="text-align:center;padding:32px;color:#6B7280;font-size:15px;font-family:'Tajawal',Arial,sans-serif;">📰 لا توجد أخبار جديدة حالياً</div>`;
        return;
      }

      // Group: emergencies first, then by time
      const sorted = data.news.sort((a, b) => {
        if (a.category === 'emergency' && b.category !== 'emergency') return -1;
        if (b.category === 'emergency' && a.category !== 'emergency') return 1;
        if (a.severity === 'high' && b.severity !== 'high') return -1;
        if (b.severity === 'high' && a.severity !== 'high') return 1;
        return new Date(b.published_at).getTime() - new Date(a.published_at).getTime();
      });

      container.innerHTML = sorted.map(item => renderItem(item)).join('');

      // Show emergency banners for unacknowledged high-severity
      for (const item of data.news) {
        if ((item.category === 'emergency' || item.severity === 'high') && item.requires_ack) {
          showEmergencyBanner(item);
        }
      }

    } catch (err) {
      container.innerHTML = `<div dir="rtl" style="color:#DC2626;font-size:13px;padding:12px;font-family:'Tajawal',Arial,sans-serif;">تعذّر تحميل الأخبار — حاول لاحقاً</div>`;
    }
  }

  let _refreshTimer = null;

  // ── Public API ───────────────────────────────────────────────
  return {
    init(containerId = 'eduos-news-panel') {
      const el = document.getElementById(containerId);
      if (!el) return;
      el.innerHTML = buildPanel();
      loadNews();

      // Start Realtime
      const user = getUser();
      if (user.role) {
        initRealtime(user);
        const indicator = document.getElementById('eduos-news-live-indicator');
        if (indicator) indicator.style.display = 'block';
      }

      // Auto-refresh every 30 min as fallback
      if (_refreshTimer) clearInterval(_refreshTimer);
      _refreshTimer = setInterval(loadNews, 30 * 60 * 1000);
    },

    refresh() {
      loadNews();
    },

    dismissBanner(newsId) {
      const banner = document.getElementById(`eduos-emergency-${newsId}`);
      if (banner) {
        banner.remove();
        document.body.style.marginTop = '';
      }
      stopVibration();
      _activeEmergencies.delete(newsId);
    },

    async acknowledge(itemId, type = 'news') {
      const user = getUser();
      stopVibration();

      // Remove banner
      this.dismissBanner(itemId);

      // Mark in DB
      try {
        await fetch(FN_URL, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${SB_ANON}` },
          body: JSON.stringify({
            action: 'acknowledge',
            [type === 'news' ? 'news_id' : 'ann_id']: itemId,
            user_role: user.role,
            user_name: user.name || user.email || 'مستخدم/ة',
            school_id: user.school_id,
          }),
        });

        // Visual feedback on button
        const btn = document.querySelector(`[onclick*="acknowledge('${itemId}'"]`);
        if (btn) {
          btn.textContent = '✅ تم التسجيل';
          btn.style.background = '#D1FAE5';
          btn.disabled = true;
        }
      } catch (e) { console.warn('[EduOSNews] ack error:', e); }
    },

    // Teacher: post class announcement
    async postClassAnn(annData) {
      const user = getUser();
      if (user.role !== 'teacher' && user.role !== 'principal' && user.role !== 'admin') {
        alert('غير مصرح — هذه الميزة للمعلمين/ات فقط');
        return;
      }

      // A-D Level B: show confirm
      const confirm = await _adConfirm('B',
        `نشر إعلان "${annData.title_ar}" للصف ${annData.class_ids?.join('، ')}؟`
      );
      if (!confirm) return;

      const resp = await fetch(FN_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${SB_ANON}` },
        body: JSON.stringify({
          action: 'post_class_ann',
          role: user.role,
          user_name: user.name,
          school_id: user.school_id,
          ...annData,
        }),
      });
      return await resp.json();
    },
  };

  function _adConfirm(level, message) {
    return new Promise(resolve => {
      const overlay = document.createElement('div');
      overlay.style.cssText = `
        position:fixed;inset:0;z-index:999997;
        background:rgba(0,0,0,.5);display:flex;align-items:center;justify-content:center;
      `;
      overlay.innerHTML = `
        <div dir="rtl" style="
          background:white;border-radius:16px;padding:28px 24px;max-width:380px;width:90%;
          font-family:'Tajawal',Arial,sans-serif;text-align:center;
        ">
          <div style="font-size:28px;margin-bottom:12px;">📢</div>
          <div style="font-size:11px;color:#6B7280;margin-bottom:8px;">مستوى الصلاحية: ${level}</div>
          <div style="font-size:16px;font-weight:600;color:#111827;margin-bottom:20px;">${message}</div>
          <div style="display:flex;gap:10px;justify-content:center;">
            <button onclick="this.closest('.ad-modal').dataset.result='yes'"
              style="background:#6C3DD6;color:white;border:none;border-radius:8px;padding:10px 24px;font-size:14px;cursor:pointer;font-family:'Tajawal',Arial,sans-serif;">
              ✅ تأكيد
            </button>
            <button onclick="this.closest('.ad-modal').dataset.result='no'"
              style="background:#F3F4F6;color:#374151;border:none;border-radius:8px;padding:10px 24px;font-size:14px;cursor:pointer;font-family:'Tajawal',Arial,sans-serif;">
              إلغاء
            </button>
          </div>
        </div>
      `;
      overlay.querySelector('div').classList.add('ad-modal');
      document.body.appendChild(overlay);

      const observer = new MutationObserver(() => {
        const modal = overlay.querySelector('.ad-modal');
        if (modal?.dataset.result) {
          observer.disconnect();
          overlay.remove();
          resolve(modal.dataset.result === 'yes');
        }
      });
      observer.observe(overlay.querySelector('.ad-modal'), { attributes: true });
    });
  }

})();

platform-pdp.js:
/**
 * platform-pdp.js — Professional Development Plan (PDP) System
 * EduOS · NAFAS FOR ARTIFICIAL INTELLIGENCE · CN-6573712
 *
 * Features:
 *  - SMART goal assistant powered by Gemini AI
 *  - Term-locked progress (only current term is editable)
 *  - Evidence upload per goal per term
 *  - Save/load from staff_pdp table
 *
 * Usage: call window.initPDP({ containerId, staffDbId, role })
 */

(function () {
  'use strict';

  var PDP = window.EduOS_PDP = {};

  // ── helpers ────────────────────────────────────────────────────────────────
  function getSB() {
    return {
      url: (window.EduOS && window.EduOS.SB_URL) || '',
      key: (window.EduOS && window.EduOS.SB_KEY) || ''
    };
  }

  async function sbGet(table, query) {
    var sb = getSB();
    var r = await fetch(sb.url + '/rest/v1/' + table + '?' + query, {
      headers: { apikey: sb.key, Authorization: 'Bearer ' + sb.key }
    });
    return r.ok ? r.json() : [];
  }

  async function sbUpsert(table, payload, onConflict) {
    var sb = getSB();
    var url = sb.url + '/rest/v1/' + table;
    if (onConflict) url += '?on_conflict=' + onConflict;
    var r = await fetch(url, {
      method: 'POST',
      headers: {
        apikey: sb.key,
        Authorization: 'Bearer ' + sb.key,
        'Content-Type': 'application/json',
        Prefer: 'resolution=merge-duplicates,return=representation'
      },
      body: JSON.stringify(payload)
    });
    return r.ok ? r.json() : null;
  }

  async function sbPatch(table, filter, payload) {
    var sb = getSB();
    var r = await fetch(sb.url + '/rest/v1/' + table + '?' + filter, {
      method: 'PATCH',
      headers: {
        apikey: sb.key,
        Authorization: 'Bearer ' + sb.key,
        'Content-Type': 'application/json',
        Prefer: 'return=representation'
      },
      body: JSON.stringify(payload)
    });
    return r.ok ? r.json() : null;
  }

  async function getSettings() {
    var rows = await sbGet('app_settings', 'key=in.(pdp_open,pdp_current_term)&select=key,value');
    var map = {};
    (rows || []).forEach(function (r) { map[r.key] = r.value; });
    return {
      pdpOpen: map['pdp_open'] === 'true',
      currentTerm: parseInt(map['pdp_current_term'] || '1', 10)
    };
  }

  // ── AI SMART analysis ───────────────────────────────────────────────────────
  async function analyzeGoal(goalText, role) {
    var sb = getSB();
    var prompt = [
      'أنت مستشار تطوير مهني متخصص في التعليم.',
      'المنصب الوظيفي: ' + (role || 'موظف تعليمي'),
      'الهدف المكتوب: "' + goalText + '"',
      '',
      'حلِّل هذا الهدف وفق معايير SMART الخمسة:',
      '1. محدَّد (Specific): هل الهدف واضح ومحدد بدقة؟',
      '2. قابل للقياس (Measurable): هل يمكن قياسه بمعيار رقمي أو نوعي واضح؟',
      '3. قابل للتحقيق (Achievable): هل هو واقعي وقابل للإنجاز خلال عام دراسي؟',
      '4. ذو صلة (Relevant): هل يرتبط بمهام وأهداف المنصب الوظيفي؟',
      '5. محدَّد زمنياً (Time-bound): هل يتضمن إطاراً زمنياً أو مراحل واضحة؟',
      '',
      'أجب بصيغة JSON فقط بهذا الشكل:',
      '{',
      '  "specific": { "score": 0-2, "note": "تعليق موجز" },',
      '  "measurable": { "score": 0-2, "note": "تعليق موجز" },',
      '  "achievable": { "score": 0-2, "note": "تعليق موجز" },',
      '  "relevant": { "score": 0-2, "note": "تعليق موجز" },',
      '  "timeBound": { "score": 0-2, "note": "تعليق موجز" },',
      '  "improved": "نسخة محسّنة ومكتملة من الهدف",',
      '  "totalScore": 0-10',
      '}',
      'score: 2=ممتاز, 1=جزئي, 0=غائب. لا تضف أي نص خارج JSON.'
    ].join('\n');

    try {
      var r = await fetch(sb.url + '/functions/v1/askAI', {
        method: 'POST',
        headers: {
          apikey: sb.key,
          Authorization: 'Bearer ' + sb.key,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ prompt: prompt })
      });
      var text = await r.text();
      var match = text.match(/\{[\s\S]*\}/);
      if (match) return JSON.parse(match[0]);
    } catch (e) { /* fall through */ }
    return null;
  }

  // ── render SMART badge ──────────────────────────────────────────────────────
  function smartBadge(score, label) {
    var color = score === 2 ? '#16a34a' : score === 1 ? '#d97706' : '#dc2626';
    var icon = score === 2 ? '&#10003;' : score === 1 ? '&#9888;' : '&#10007;';
    return '<span style="display:inline-flex;align-items:center;gap:4px;padding:3px 9px;border-radius:20px;font-size:12px;font-weight:600;color:#fff;background:' + color + ';margin:2px">' + icon + ' ' + label + '</span>';
  }

  // ── term label ──────────────────────────────────────────────────────────────
  function termLabel(t) {
    return ['', 'الفصل الأول', 'الفصل الثاني', 'الفصل الثالث'][t] || ('الفصل ' + t);
  }

  // ── goal card HTML ──────────────────────────────────────────────────────────
  function goalCardHTML(i, g, planningOpen, currentTerm, termData, readOnly) {
    var num = i + 1;
    var termKeys = [
      { key: 'term1_data', label: 'الفصل الأول', t: 1 },
      { key: 'term2_data', label: 'الفصل الثاني', t: 2 },
      { key: 'term3_data', label: 'الفصل الثالث', t: 3 }
    ];

    var goalVal = g || '';
    var html = '<div class="pdp-goal-card" id="pdp-goal-' + i + '" style="background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:20px;margin-bottom:16px">';
    html += '<div style="display:flex;align-items:center;gap:10px;margin-bottom:14px">';
    html += '<div style="width:32px;height:32px;border-radius:50%;background:linear-gradient(135deg,#6C3DD6,#22D3EE);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700;flex-shrink:0">' + num + '</div>';
    html += '<span style="font-weight:700;color:#1e293b;font-size:15px">الهدف ' + num + '</span>';
    html += '</div>';

    if (planningOpen && !readOnly) {
      // Goal text area
      html += '<div style="margin-bottom:12px">';
      html += '<label style="font-size:13px;color:#64748b;display:block;margin-bottom:4px">&#127919; الهدف التطويري</label>';
      html += '<textarea id="goal-text-' + i + '" rows="2" style="width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:8px;font-family:Tajawal,Arial,sans-serif;font-size:14px;resize:vertical;box-sizing:border-box" placeholder="اكتب هدفك هنا...">' + goalVal + '</textarea>';
      html += '<button onclick="EduOS_PDP.analyzeGoalUI(' + i + ')" style="margin-top:6px;padding:6px 14px;background:linear-gradient(135deg,#6C3DD6,#22D3EE);color:#fff;border:none;border-radius:8px;cursor:pointer;font-family:Tajawal,Arial,sans-serif;font-size:13px">&#128161; تحليل SMART</button>';
      html += '</div>';
      html += '<div id="smart-result-' + i + '" style="margin-bottom:12px"></div>';

      // Implementation plan
      html += '<div style="margin-bottom:12px">';
      html += '<label style="font-size:13px;color:#64748b;display:block;margin-bottom:4px">&#128196; الخطة التنفيذية</label>';
      var planVal = (window._pdpCurrentData && window._pdpCurrentData['plan_' + num]) || '';
      html += '<textarea id="plan-text-' + i + '" rows="3" style="width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:8px;font-family:Tajawal,Arial,sans-serif;font-size:14px;resize:vertical;box-sizing:border-box" placeholder="كيف ستُنفّذ هذا الهدف؟ ما الخطوات والموارد والمعايير؟">' + planVal + '</textarea>';
      html += '</div>';

    } else {
      // Read-only goal display
      html += '<div style="background:#f8fafc;border-radius:8px;padding:12px;margin-bottom:12px">';
      html += '<p style="margin:0;color:#1e293b;font-size:14px">' + (goalVal || '<em style="color:#94a3b8">لم يُكتب بعد</em>') + '</p>';
      var planVal = (window._pdpCurrentData && window._pdpCurrentData['plan_' + num]) || '';
      if (planVal) {
        html += '<p style="margin:8px 0 0;color:#64748b;font-size:13px;border-top:1px solid #e2e8f0;padding-top:8px">&#128196; ' + planVal + '</p>';
      }
      html += '</div>';
    }

    // Term progress strips (only if not in planning mode)
    if (!planningOpen || readOnly) {
      html += '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px">';
      termKeys.forEach(function (tk) {
        var tData = (termData && termData[tk.key]) || {};
        var gKey = 'goal' + num;
        var prog = (tData[gKey] && tData[gKey].progress !== undefined) ? tData[gKey].progress : null;
        var evi = (tData[gKey] && tData[gKey].evidence) ? tData[gKey].evidence : '';
        var isOpen = (tk.t === currentTerm) && !readOnly;
        var isFuture = tk.t > currentTerm;
        var isBg = isFuture ? '#f1f5f9' : '#fff';
        var isBorder = isFuture ? '#e2e8f0' : (isOpen ? '#6C3DD6' : '#e2e8f0');
        var lockIcon = isFuture ? ' &#128274;' : '';

        html += '<div style="border:1px solid ' + isBorder + ';border-radius:10px;padding:10px;background:' + isBg + '">';
        html += '<div style="font-size:12px;font-weight:700;color:' + (isFuture ? '#94a3b8' : '#475569') + ';margin-bottom:8px">' + tk.label + lockIcon + '</div>';

        if (isFuture) {
          html += '<div style="font-size:11px;color:#94a3b8;text-align:center;padding:8px 0">&#128274; مقفل</div>';
        } else if (isOpen) {
          html += '<label style="font-size:11px;color:#64748b;display:block;margin-bottom:3px">نسبة الإنجاز</label>';
          html += '<input type="number" id="prog-' + i + '-' + tk.t + '" min="0" max="100" value="' + (prog !== null ? prog : '') + '" style="width:100%;padding:5px 8px;border:1px solid #cbd5e1;border-radius:6px;font-size:13px;box-sizing:border-box" placeholder="0-100">';
          html += '<label style="font-size:11px;color:#64748b;display:block;margin-top:6px;margin-bottom:3px">الأدلة والملاحظات</label>';
          html += '<textarea id="evi-' + i + '-' + tk.t + '" rows="2" style="width:100%;padding:5px 8px;border:1px solid #cbd5e1;border-radius:6px;font-size:12px;resize:none;box-sizing:border-box" placeholder="أدلة / رابط / ملاحظة...">' + evi + '</textarea>';
        } else {
          // Past term — read only
          var pct = prog !== null ? prog : '—';
          var pColor = prog >= 80 ? '#16a34a' : prog >= 50 ? '#d97706' : '#dc2626';
          html += '<div style="text-align:center;font-size:20px;font-weight:700;color:' + (prog !== null ? pColor : '#94a3b8') + '">' + (prog !== null ? pct + '%' : '—') + '</div>';
          if (evi) html += '<div style="font-size:11px;color:#64748b;margin-top:4px;word-break:break-word">' + evi + '</div>';
        }
        html += '</div>';
      });
      html += '</div>'; // end grid
    }

    html += '</div>'; // end goal card
    return html;
  }

  // ── main render ─────────────────────────────────────────────────────────────
  PDP.init = async function (opts) {
    var containerId = opts.containerId;
    var staffDbId = opts.staffDbId;
    var role = opts.role || 'موظف';
    var container = document.getElementById(containerId);
    if (!container) return;

    container.innerHTML = '<div style="text-align:center;padding:40px;color:#64748b"><div style="font-size:24px">&#8987;</div><div style="margin-top:8px">جار تحميل خطة التطوير...</div></div>';

    var settings = await getSettings();
    var rows = await sbGet('staff_pdp', 'staff_db_id=eq.' + encodeURIComponent(staffDbId) + '&limit=1&select=*');
    var pdp = (rows && rows.length > 0) ? rows[0] : null;
    window._pdpCurrentData = pdp;
    window._pdpStaffDbId = staffDbId;
    window._pdpRole = role;
    window._pdpSettings = settings;

    // Load term data from DB
    var termData = {};
    if (pdp) {
      termData.term1_data = pdp.term1_data || {};
      termData.term2_data = pdp.term2_data || {};
      termData.term3_data = pdp.term3_data || {};
    }
    window._pdpTermData = termData;

    var planningOpen = settings.pdpOpen;
    var currentTerm = settings.currentTerm;

    var html = '';

    // ── Status bar ───────────────────────────────────────────────────────────
    html += '<div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;margin-bottom:20px">';
    html += '<div>';
    html += '<h3 style="margin:0;color:#1e293b;font-size:18px">&#127919; خطة التطوير المهني</h3>';
    html += '<p style="margin:4px 0 0;color:#64748b;font-size:13px">السنة الأكاديمية: ' + (pdp ? pdp.academic_year : '—') + '</p>';
    html += '</div>';

    // Status pill
    if (planningOpen) {
      html += '<div style="padding:6px 16px;background:#fef9c3;color:#854d0e;border-radius:20px;font-size:13px;font-weight:600">&#9997; فترة كتابة الخطة مفتوحة</div>';
    } else {
      html += '<div style="padding:6px 16px;background:#f0fdf4;color:#166534;border-radius:20px;font-size:13px;font-weight:600">&#128336; ' + termLabel(currentTerm) + ' — جارٍ</div>';
    }
    html += '</div>';

    // ── No PDP yet (planning closed) ────────────────────────────────────────
    if (!pdp && !planningOpen) {
      html += '<div style="text-align:center;padding:60px 20px;background:#f8fafc;border-radius:14px;border:2px dashed #cbd5e1">';
      html += '<div style="font-size:48px;margin-bottom:12px">&#128196;</div>';
      html += '<p style="color:#475569;font-size:15px">لم تُكتب خطة تطوير لهذا العام بعد.</p>';
      html += '<p style="color:#94a3b8;font-size:13px">تُفتح نافذة كتابة الخطة في نهاية الفصل الثالث.</p>';
      html += '</div>';
      container.innerHTML = html;
      return;
    }

    // ── Planning mode ────────────────────────────────────────────────────────
    if (planningOpen) {
      html += '<div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:12px;padding:14px 18px;margin-bottom:20px">';
      html += '<p style="margin:0;color:#1e40af;font-size:13px">&#128161; <strong>مساعد الأهداف الذكية (SMART)</strong> — اكتب هدفك ثم اضغط "تحليل SMART" لتحسينه وضمان استيفاء المعايير قبل الحفظ.</p>';
      html += '</div>';
    }

    // ── Goal cards ───────────────────────────────────────────────────────────
    var goals = [
      pdp ? pdp.goal_1 : '',
      pdp ? pdp.goal_2 : '',
      pdp ? pdp.goal_3 : ''
    ];

    html += '<div id="pdp-goals-container">';
    for (var i = 0; i < 3; i++) {
      html += goalCardHTML(i, goals[i], planningOpen, currentTerm, termData, false);
    }
    html += '</div>';

    // ── Action buttons ───────────────────────────────────────────────────────
    html += '<div style="display:flex;gap:12px;justify-content:flex-end;margin-top:20px">';
    if (planningOpen) {
      html += '<button onclick="EduOS_PDP.savePlan()" style="padding:10px 28px;background:linear-gradient(135deg,#6C3DD6,#22D3EE);color:#fff;border:none;border-radius:10px;cursor:pointer;font-family:Tajawal,Arial,sans-serif;font-size:15px;font-weight:600">&#128190; حفظ الخطة</button>';
    } else {
      html += '<button onclick="EduOS_PDP.saveProgress()" style="padding:10px 28px;background:linear-gradient(135deg,#6C3DD6,#22D3EE);color:#fff;border:none;border-radius:10px;cursor:pointer;font-family:Tajawal,Arial,sans-serif;font-size:15px;font-weight:600">&#128190; حفظ التقدم</button>';
    }
    html += '</div>';

    // ── Principal note (if any) ──────────────────────────────────────────────
    if (pdp && pdp.principal_note) {
      html += '<div style="margin-top:20px;background:#fef3c7;border:1px solid #fde68a;border-radius:12px;padding:14px 18px">';
      html += '<p style="margin:0;color:#92400e;font-size:13px"><strong>&#128204; ملاحظة المدير/ة:</strong> ' + pdp.principal_note + '</p>';
      html += '</div>';
    }

    container.innerHTML = html;
  };

  // ── analyzeGoalUI — called from button ──────────────────────────────────────
  PDP.analyzeGoalUI = async function (i) {
    var textEl = document.getElementById('goal-text-' + i);
    var resultEl = document.getElementById('smart-result-' + i);
    if (!textEl || !resultEl) return;

    var goalText = textEl.value.trim();
    if (!goalText) { resultEl.innerHTML = '<p style="color:#dc2626;font-size:13px">&#9888; الرجاء كتابة الهدف أولاً.</p>'; return; }

    resultEl.innerHTML = '<div style="text-align:center;padding:16px;color:#64748b;font-size:13px">&#128161; يحلّل الذكاء الاصطناعي هدفك...</div>';

    var analysis = await analyzeGoal(goalText, window._pdpRole);
    if (!analysis) {
      resultEl.innerHTML = '<p style="color:#dc2626;font-size:13px">&#9888; تعذّر التحليل، حاول مجدداً.</p>';
      return;
    }

    var labels = {
      specific: 'محدَّد',
      measurable: 'قابل للقياس',
      achievable: 'قابل للتحقيق',
      relevant: 'ذو صلة',
      timeBound: 'محدَّد زمنياً'
    };

    var html = '<div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:12px;padding:14px">';

    // SMART badges
    html += '<div style="margin-bottom:10px">';
    Object.keys(labels).forEach(function (k) {
      if (analysis[k]) html += smartBadge(analysis[k].score, labels[k]);
    });
    html += '</div>';

    // Notes per criterion
    html += '<div style="display:grid;gap:6px;margin-bottom:12px">';
    Object.keys(labels).forEach(function (k) {
      if (!analysis[k]) return;
      var s = analysis[k].score;
      var color = s === 2 ? '#16a34a' : s === 1 ? '#d97706' : '#dc2626';
      html += '<div style="font-size:12px;color:#475569"><span style="color:' + color + ';font-weight:700">' + labels[k] + ':</span> ' + analysis[k].note + '</div>';
    });
    html += '</div>';

    // Score bar
    var total = analysis.totalScore || 0;
    var pct = (total / 10) * 100;
    var barColor = total >= 8 ? '#16a34a' : total >= 5 ? '#d97706' : '#dc2626';
    html += '<div style="display:flex;align-items:center;gap:10px;margin-bottom:12px">';
    html += '<span style="font-size:13px;color:#475569;white-space:nowrap">تقييم الهدف:</span>';
    html += '<div style="flex:1;background:#e2e8f0;border-radius:4px;height:8px"><div style="width:' + pct + '%;height:100%;background:' + barColor + ';border-radius:4px"></div></div>';
    html += '<span style="font-size:13px;font-weight:700;color:' + barColor + ';white-space:nowrap">' + total + '/10</span>';
    html += '</div>';

    // Improved version
    if (analysis.improved) {
      html += '<div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;padding:10px;margin-bottom:10px">';
      html += '<p style="margin:0 0 6px;font-size:12px;color:#166534;font-weight:700">&#10024; الهدف المقترح المحسَّن:</p>';
      html += '<p style="margin:0;font-size:13px;color:#1e293b">' + analysis.improved + '</p>';
      html += '<button onclick="document.getElementById(\'goal-text-' + i + '\').value=' + JSON.stringify(analysis.improved) + ';document.getElementById(\'smart-result-' + i + '\').innerHTML=\'\'" style="margin-top:8px;padding:5px 14px;background:#16a34a;color:#fff;border:none;border-radius:6px;cursor:pointer;font-family:Tajawal,Arial,sans-serif;font-size:12px">&#10004; قبول الاقتراح</button>';
      html += '</div>';
    }

    html += '</div>';
    resultEl.innerHTML = html;
  };

  // ── savePlan ─────────────────────────────────────────────────────────────────
  PDP.savePlan = async function () {
    var goals = [0, 1, 2].map(function (i) {
      var el = document.getElementById('goal-text-' + i);
      return el ? el.value.trim() : '';
    });
    var plans = [0, 1, 2].map(function (i) {
      var el = document.getElementById('plan-text-' + i);
      return el ? el.value.trim() : '';
    });

    if (!goals[0] && !goals[1] && !goals[2]) {
      alert('الرجاء كتابة هدف واحد على الأقل.');
      return;
    }

    var sb = getSB();
    var staffDbId = window._pdpStaffDbId;
    var existing = window._pdpCurrentData;

    var year = new Date().getFullYear();
    var academicYear = (new Date().getMonth() < 8 ? (year - 1) : year) + '-' + (new Date().getMonth() < 8 ? year : year + 1);

    var payload = {
      staff_db_id: staffDbId,
      academic_year: academicYear,
      goal_1: goals[0],
      goal_2: goals[1],
      goal_3: goals[2],
      plan_1: plans[0],
      plan_2: plans[1],
      plan_3: plans[2],
      status: 'مسودة'
    };

    var btn = document.querySelector('[onclick="EduOS_PDP.savePlan()"]');
    if (btn) { btn.disabled = true; btn.textContent = '...جار الحفظ'; }

    var result;
    if (existing && existing.id) {
      result = await sbPatch('staff_pdp', 'id=eq.' + existing.id, payload);
    } else {
      result = await sbUpsert('staff_pdp', payload, 'staff_db_id,academic_year');
    }

    if (result) {
      window._pdpCurrentData = Array.isArray(result) ? result[0] : result;
      showToast('&#10004; تم حفظ الخطة بنجاح');
    } else {
      showToast('&#9888; تعذّر الحفظ', true);
    }
    if (btn) { btn.disabled = false; btn.textContent = '💾 حفظ الخطة'; }
  };

  // ── saveProgress ──────────────────────────────────────────────────────────────
  PDP.saveProgress = async function () {
    var currentTerm = (window._pdpSettings && window._pdpSettings.currentTerm) || 1;
    var existing = window._pdpCurrentData;
    if (!existing || !existing.id) { alert('لا توجد خطة مسجّلة.'); return; }

    var termKey = 'term' + currentTerm + '_data';
    var termData = existing[termKey] || {};

    [0, 1, 2].forEach(function (i) {
      var gKey = 'goal' + (i + 1);
      var progEl = document.getElementById('prog-' + i + '-' + currentTerm);
      var eviEl = document.getElementById('evi-' + i + '-' + currentTerm);
      if (progEl) {
        termData[gKey] = {
          progress: parseInt(progEl.value || '0', 10),
          evidence: eviEl ? eviEl.value.trim() : ''
        };
      }
    });

    var patch = {};
    patch[termKey] = termData;

    // Calc overall progress
    var total = 0; var count = 0;
    [1, 2, 3].forEach(function (t) {
      var d = existing['term' + t + '_data'] || {};
      [1, 2, 3].forEach(function (g) {
        var gd = d['goal' + g];
        if (gd && gd.progress !== undefined) { total += gd.progress; count++; }
      });
    });
    patch.progress = count > 0 ? Math.round(total / count) : 0;

    var btn = document.querySelector('[onclick="EduOS_PDP.saveProgress()"]');
    if (btn) { btn.disabled = true; btn.textContent = '...جار الحفظ'; }

    var result = await sbPatch('staff_pdp', 'id=eq.' + existing.id, patch);
    if (result) {
      window._pdpCurrentData = Array.isArray(result) ? result[0] : result;
      showToast('&#10004; تم حفظ التقدم بنجاح');
    } else {
      showToast('&#9888; تعذّر الحفظ', true);
    }
    if (btn) { btn.disabled = false; btn.textContent = '💾 حفظ التقدم'; }
  };

  // ── toast helper ──────────────────────────────────────────────────────────────
  function showToast(msg, isError) {
    var t = document.createElement('div');
    t.innerHTML = msg;
    t.style.cssText = 'position:fixed;bottom:24px;left:50%;transform:translateX(-50%);padding:12px 24px;border-radius:10px;color:#fff;font-family:Tajawal,Arial,sans-serif;font-size:14px;z-index:9999;box-shadow:0 4px 20px rgba(0,0,0,0.2);background:' + (isError ? '#dc2626' : '#16a34a');
    document.body.appendChild(t);
    setTimeout(function () { t.remove(); }, 3500);
  }

  // ── public alias ──────────────────────────────────────────────────────────────
  PDP.initPDP = PDP.init;

})();

